N = 100_000
samples = rand(rng, N)
estimate = mean(g.(samples))
@printf("True value          : %.6f\n", true_value)
@printf("MC estimate (N=%d) : %.6f\n", N, estimate)
@printf("Absolute error      : %.6e\n", abs(estimate - true_value))

# Empirical RMSE versus sigma / sqrt(N).
sizes = [10, 30, 100, 300, 1000, 3000, 10_000, 30_000, 100_000]
trials = 200
for n in sizes
    errs = [mean(g.(rand(rng, n))) - true_value for _ in 1:trials]
    @printf("N=%7d  RMSE=%.6e\n", n, sqrt(mean(errs .^ 2)))
end


// Cargo.toml: rand = "0.8", libm = "0.2"
use rand::rngs::StdRng;
use rand::{Rng, SeedableRng};

fn g(x: f64) -&gt; f64 {
    (-x * x).exp()
}

fn main() {
    let mut rng = StdRng::seed_from_u64(0);
    // sqrt(pi)/2 * erf(1) computed via libm::erf.
    let true_value = std::f64::consts::PI.sqrt() / 2.0 * libm::erf(1.0);

    let n = 100_000;
    let sum: f64 = (0..n).map(|_| g(rng.gen::&lt;f64&gt;())).sum();
    let estimate = sum / n as f64;
    println!("True value         : {:.6}", true_value);
    println!("MC estimate (N={}) : {:.6}", n, estimate);
    println!("Absolute error     : {:.6e}", (estimate - true_value).abs());

    // Empirical RMSE versus sigma / sqrt(N).
    let sizes = [10usize, 30, 100, 300, 1000, 3000, 10_000, 30_000, 100_000];
    let trials = 200;
    for &m in sizes.iter() {
        let mut sq = 0.0;
        for _ in 0..trials {
            let s: f64 = (0..m).map(|_| g(rng.gen::&lt;f64&gt;())).sum::&lt;f64&gt;() / m as f64;
            let e = s - true_value;
            sq += e * e;
        }
        println!("N={:7}  RMSE={:.6e}", m, (sq / trials as f64).sqrt());
    }
}

45.6 6. Optimizers from Scratch: A Worked Comparison
Theory predicts that on an ill conditioned objective, plain SGD zigzags, momentum damps the oscillation, and Adam adapts its per coordinate scale to make rapid progress in every direction at once. The cleanest way to see this is to implement all three from scratch and watch them descend the same surface. The test function below is a quadratic bowl \(f(x, y) = \tfrac{1}{2}(x^2 + 20 y^2)\), deliberately stretched twentyfold along \(y\) so that a learning rate large enough to move in \(x\) would diverge in \(y\) under plain SGD. The cell is fully self contained and runs as written.

PythonJuliaRust




Code
import numpy as np
import matplotlib.pyplot as plt

np.random.seed(0)

# Ill conditioned quadratic bowl: f(x, y) = 0.5 * (a x^2 + b y^2)
a, b = 1.0, 20.0

def f(p):
    x, y = p
    return 0.5 * (a * x * x + b * y * y)

def grad(p):
    x, y = p
    return np.array([a * x, b * y])

start = np.array([-9.0, -4.0])
n_steps = 100

def run_sgd(lr):
    p = start.copy()
    traj = [p.copy()]
    for _ in range(n_steps):
        p = p - lr * grad(p)
        traj.append(p.copy())
    return np.array(traj)

def run_momentum(lr, mu=0.9):
    p, v = start.copy(), np.zeros(2)
    traj = [p.copy()]
    for _ in range(n_steps):
        v = mu * v + grad(p)
        p = p - lr * v
        traj.append(p.copy())
    return np.array(traj)

def run_adam(lr, b1=0.9, b2=0.999, eps=1e-8):
    p, m, v = start.copy(), np.zeros(2), np.zeros(2)
    traj = [p.copy()]
    for t in range(1, n_steps + 1):
        g = grad(p)
        m = b1 * m + (1 - b1) * g
        v = b2 * v + (1 - b2) * g * g
        m_hat = m / (1 - b1 ** t)
        v_hat = v / (1 - b2 ** t)
        p = p - lr * m_hat / (np.sqrt(v_hat) + eps)
        traj.append(p.copy())
    return np.array(traj)

runs = {
    "SGD": run_sgd(lr=0.04),
    "Momentum": run_momentum(lr=0.018, mu=0.9),
    "Adam": run_adam(lr=0.6),
}

print(f"Final loss after {n_steps} steps:")
for name, tr in runs.items():
    print(f"  {name:9s} loss = {f(tr[-1]):.3e}")

fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))

xs, ys = np.linspace(-10, 10, 200), np.linspace(-6, 6, 200)
X, Y = np.meshgrid(xs, ys)
Z = 0.5 * (a * X ** 2 + b * Y ** 2)
ax1.contour(X, Y, Z, levels=np.logspace(-1, 3, 20), cmap="Greys", alpha=0.5)
for name, tr in runs.items():
    ax1.plot(tr[:, 0], tr[:, 1], marker="o", ms=3, label=name)
ax1.set_title("Trajectories on an ill conditioned bowl")
ax1.set_xlabel("x"); ax1.set_ylabel("y"); ax1.legend()

for name, tr in runs.items():
    ax2.semilogy([f(p) for p in tr], label=name)
ax2.set_title("Convergence curves")
ax2.set_xlabel("step"); ax2.set_ylabel("loss (log scale)"); ax2.legend()

plt.tight_layout()
plt.show()


Final loss after 100 steps:
  SGD       loss = 1.153e-02
  Momentum  loss = 5.442e-03
  Adam      loss = 8.006e-04









Running the cell prints a final loss of roughly \(1.2 \times 10^{-2}\) for SGD, \(5.4 \times 10^{-3}\) for momentum, and \(8.0 \times 10^{-4}\) for Adam. The contour plot shows SGD crawling down the steep \(y\) wall in tiny careful steps, momentum overshooting and oscillating before settling, and Adam cutting almost straight to the floor because its second moment estimate rescales the \(y\) coordinate to match the \(x\) coordinate. The ordering on this surface matches the theory above: adaptivity buys the most when the curvature is badly unbalanced.


# Illustrative: same three optimizers in Julia.
using LinearAlgebra

a, b = 1.0, 20.0
f(p) = 0.5 * (a * p[1]^2 + b * p[2]^2)
grad(p) = [a * p[1], b * p[2]]

start = [-9.0, -4.0]
nsteps = 100

function run_adam(lr; b1=0.9, b2=0.999, eps=1e-8)
    p = copy(start); m = zeros(2); v = zeros(2)
    for t in 1:nsteps
        g = grad(p)
        m = b1 .* m .+ (1 - b1) .* g
        v = b2 .* v .+ (1 - b2) .* (g .^ 2)
        mhat = m ./ (1 - b1^t)
        vhat = v ./ (1 - b2^t)
        p = p .- lr .* mhat ./ (sqrt.(vhat) .+ eps)
    end
    return p
end

p = run_adam(0.6)
println("Adam final loss = ", f(p))


// Illustrative: Adam on the same 2D bowl.
fn grad(p: [f64; 2]) -&gt; [f64; 2] {
    [1.0 * p[0], 20.0 * p[1]]
}
fn f(p: [f64; 2]) -&gt; f64 {
    0.5 * (1.0 * p[0] * p[0] + 20.0 * p[1] * p[1])
}

fn main() {
    let (lr, b1, b2, eps) = (0.6_f64, 0.9_f64, 0.999_f64, 1e-8_f64);
    let mut p = [-9.0_f64, -4.0_f64];
    let mut m = [0.0_f64; 2];
    let mut v = [0.0_f64; 2];
    for t in 1..=100 {
        let g = grad(p);
        for i in 0..2 {
            m[i] = b1 * m[i] + (1.0 - b1) * g[i];
            v[i] = b2 * v[i] + (1.0 - b2) * g[i] * g[i];
            let m_hat = m[i] / (1.0 - b1.powi(t));
            let v_hat = v[i] / (1.0 - b2.powi(t));
            p[i] -= lr * m_hat / (v_hat.sqrt() + eps);
        }
    }
    println!("Adam final loss = {}", f(p));
}

49.10 10. The Stable Softmax Across Languages
The shifted softmax is the same algorithm in any language. The pattern is always subtract the maximum, exponentiate, then normalize. Below the Python version is executable and the others are illustrative.

PythonJuliaRust




Code
import numpy as np

def softmax(x):
    x = np.asarray(x, dtype=np.float64)
    z = x - np.max(x)        # shift for stability
    e = np.exp(z)
    return e / np.sum(e)

print(softmax([1000.0, 1001.0, 1002.0]))


[0.09003057 0.24472847 0.66524096]




function softmax(x::AbstractVector{&lt;:Real})
    c = maximum(x)            # shift for stability
    e = exp.(x .- c)
    return e ./ sum(e)
end

println(softmax([1000.0, 1001.0, 1002.0]))


fn softmax(x: &[f64]) -&gt; Vec&lt;f64&gt; {
    let c = x.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let exps: Vec&lt;f64&gt; = x.iter().map(|&v| (v - c).exp()).collect();
    let sum: f64 = exps.iter().sum();
    exps.iter().map(|&e| e / sum).collect()
}

fn main() {
    let p = softmax(&[1000.0, 1001.0, 1002.0]);
    println!("{:?}", p);
}

55.3 3. GraphQL APIs

55.3.1 3.1 One endpoint, declared queries
GraphQL exposes a single endpoint, usually /graphql, and lets the client declare the exact shape it wants. You send a query describing fields, and the server returns precisely those fields, nested as requested. The earlier three call customer view collapses into one request.
query {
  customer(id: "4821") {
    name
    invoices(last: 5) { amount status }
    tickets(open: true) { subject createdAt }
  }
}
The response mirrors the query structure, so a deeply nested object arrives in a single round trip. This solves both under fetching and over fetching at once, which is why data heavy front ends and aggregation layers favor it.


55.3.2 3.2 Costs and cautions
The flexibility has a price. Caching is harder because every query can differ, so the simple URL based caching that REST enjoys does not apply. A careless client can also request an enormous nested structure that forces the server to do heavy work, so mature GraphQL servers impose query depth limits and cost analysis. From the data engineer’s side, error handling is subtler: GraphQL often returns HTTP 200 even when part of the query failed, placing the failure inside an errors array in the body. You must inspect that array rather than trusting the status code alone.


55.3.3 3.3 Choosing between REST and GraphQL
There is no universal winner. Choose REST when the API is simple, caching matters, or the provider only offers REST. Choose GraphQL when you assemble complex nested records, when network round trips are costly, or when different consumers need different field subsets from the same graph. In practice you will consume both within a single project, so fluency in each is the realistic goal.

152.2 2. Random Partitioning and Tree Construction
An Isolation Tree, or iTree, is built by recursive random partitioning. Given a sample of data, the procedure selects a feature uniformly at random, then selects a split value uniformly at random between the minimum and maximum observed values of that feature within the current node. The data is partitioned into two children by the split, and the procedure recurses on each child.


Code
import numpy as np

rng = np.random.default_rng(0)


class ExternalNode:
    def __init__(self, size):
        self.size = size


class InternalNode:
    def __init__(self, q, p, left, right):
        self.q, self.p, self.left, self.right = q, p, left, right


def build_itree(X, depth, limit, rng):
    if depth &gt;= limit or X.shape[0] &lt;= 1:
        return ExternalNode(size=X.shape[0])
    q = rng.integers(X.shape[1])
    lo, hi = X[:, q].min(), X[:, q].max()
    if lo == hi:
        return ExternalNode(size=X.shape[0])
    p = rng.uniform(lo, hi)
    left = X[X[:, q] &lt; p]
    right = X[X[:, q] &gt;= p]
    return InternalNode(q, p,
                        build_itree(left, depth + 1, limit, rng),
                        build_itree(right, depth + 1, limit, rng))


def c(n):
    if n &lt;= 1:
        return 0.0
    H = np.log(n - 1) + 0.5772156649  # harmonic number approximation
    return 2.0 * H - 2.0 * (n - 1) / n


def path_length(x, node, depth=0):
    if isinstance(node, ExternalNode):
        return depth + c(node.size)
    if x[node.q] &lt; node.p:
        return path_length(x, node.left, depth + 1)
    return path_length(x, node.right, depth + 1)


psi = 256
normal = rng.normal(0, 1, size=(psi, 2))
limit = int(np.ceil(np.log2(psi)))
tree = build_itree(normal, 0, limit, rng)

center = np.array([0.0, 0.0])
outlier = np.array([6.0, 6.0])
print("path length, center point :", round(path_length(center, tree), 3))
print("path length, far outlier  :", round(path_length(outlier, tree), 3))
print("normalizing constant c(psi):", round(c(psi), 3))


path length, center point : 12.278
path length, far outlier  : 5.0
normalizing constant c(psi): 10.245


Two design choices matter. First, each tree is built from a small subsample of the data rather than the full dataset. The original work recommends a subsampling size of \(\psi = 256\). This is not merely an efficiency hack. Small samples reduce two pathologies known as swamping and masking. Swamping occurs when normal points adjacent to a cluster of anomalies are themselves flagged. Masking occurs when a dense cluster of anomalies hides them from isolation. A small sample thins out the data so that anomalies remain sparse and separable rather than forming clusters that resist isolation.
Second, the recursion is capped at a height limit. Because anomalies are isolated near the top of the tree, there is no value in growing branches deep into the normal data. The height limit is set to \(\lceil \log_2 \psi \rceil\), the average height of a tree built on \(\psi\) points, since paths longer than this carry little discriminative information about anomalies.
An Isolation Forest is an ensemble of \(t\) such trees, each built on an independent subsample. The original work uses \(t = 100\). Averaging over the ensemble smooths the variance introduced by random feature and split selection, yielding a stable estimate of expected path length.

186.2 2. The Rectified Linear Unit
The rectified linear unit replaces smooth saturation with a piecewise linear hinge, \[
\mathrm{ReLU}(x) = \max(0, x) =
\begin{cases}
x & x &gt; 0, \\
0 & x \le 0.
\end{cases}
\] Its derivative is the Heaviside step, \[
\mathrm{ReLU}'(x) =
\begin{cases}
1 & x &gt; 0, \\
0 & x &lt; 0,
\end{cases}
\] with the subgradient at \(x = 0\) conventionally taken to be \(0\) or any value in \([0, 1]\). In code the forward and backward passes are trivial.
def relu(x):
    return np.maximum(0.0, x)

def relu_grad(x):
    return (x &gt; 0).astype(x.dtype)

186.2.1 2.1 Why ReLU Helps Gradients
The decisive property is that for any active unit, where \(x &gt; 0\), the local derivative is exactly \(1\). Substituting into the depthwise product above, an active path contributes a factor of \(1\) rather than a factor bounded by \(0.25\). Gradients therefore neither shrink nor swell purely because of the activation, and the error signal can traverse many layers without the geometric decay that plagues sigmoids. The network instead relies on careful weight initialization, such as the He scheme that sets the weight variance to \(2 / n_{\text{in}}\), to keep the magnitude of forward activations and backward gradients stable across depth.
Three further properties matter in practice. First, ReLU induces sparsity: roughly half of the units in a randomly initialized layer output exactly zero, which yields representations that are sparse and often more linearly separable. Second, the function and its gradient cost a single comparison, so it is computationally cheaper than evaluating an exponential. Third, ReLU is scale equivariant for positive scaling, since \(\mathrm{ReLU}(\alpha x) = \alpha\,\mathrm{ReLU}(x)\) for \(\alpha &gt; 0\), which interacts cleanly with normalization layers.
It is worth being precise about what ReLU does and does not solve. It mitigates the vanishing gradient that arises from activation saturation, but it does not by itself prevent exploding gradients from large weight norms, nor does it remove the need for normalization in very deep networks. The benefit is local: each active unit passes its gradient through undistorted.

186.4 4. Leaky ReLU
The simplest fix introduces a small fixed slope \(\alpha\) on the negative side, \[
\mathrm{LReLU}(x) =
\begin{cases}
x & x &gt; 0, \\
\alpha x & x \le 0,
\end{cases}
\qquad
\mathrm{LReLU}'(x) =
\begin{cases}
1 & x &gt; 0, \\
\alpha & x &lt; 0,
\end{cases}
\] with \(\alpha\) a small positive constant, typically \(0.01\). Because the derivative on the negative side is \(\alpha &gt; 0\) rather than \(0\), a unit with negative pre-activation still receives a gradient and can be nudged back toward the active region. Dead units therefore cannot become permanently inert under leaky ReLU.
def leaky_relu(x, alpha=0.01):
    return np.where(x &gt; 0, x, alpha * x)
The cost of this insurance is small. With \(\alpha = 0.01\) the negative branch is nearly flat, so the function behaves almost like ReLU on typical inputs while retaining a trickle of gradient where it matters. The price is the loss of exact sparsity, since negative pre-activations now produce small nonzero outputs, and the introduction of a hyperparameter that must be chosen. In practice \(\alpha\) is rarely tuned with care, and the default value works adequately across many architectures. The empirical gains over ReLU are often modest, which is part of why plain ReLU remains a common default despite its known pathology.

186.5 5. Parametric ReLU
Parametric ReLU removes the guesswork by treating the negative slope as a learnable parameter rather than a fixed constant. The form is identical to leaky ReLU, \[
\mathrm{PReLU}(x) =
\begin{cases}
x & x &gt; 0, \\
a\, x & x \le 0,
\end{cases}
\] but \(a\) is learned by gradient descent jointly with the weights. The gradient of the loss with respect to the slope, accumulated over the units that share it, is \[
\frac{\partial \mathcal{L}}{\partial a}
= \sum_{x \le 0} \frac{\partial \mathcal{L}}{\partial \mathrm{PReLU}(x)} \cdot x,
\] since \(\partial\,\mathrm{PReLU}(x) / \partial a = x\) on the negative branch and \(0\) on the positive branch. The slope can be shared across an entire channel, giving one parameter per feature map, or shared across the whole layer, giving a single scalar. The number of added parameters is negligible relative to the weight matrices, so PReLU introduces essentially no risk of overfitting on large datasets.
# a is a learnable parameter, updated by the optimizer
def prelu(x, a):
    return np.where(x &gt; 0, x, a * x)
The advantage of PReLU is adaptivity: each channel can discover the negative slope that best fits its role, and in the original work this raised accuracy on large scale image classification at near zero cost. Learned slopes are sometimes substantially larger than the leaky default, which suggests that a single hand picked constant is not optimal everywhere. The tradeoffs are that the extra parameters interact with weight decay, so practitioners usually exclude \(a\) from regularization, and that on small datasets the added flexibility can slightly increase variance. PReLU is best viewed as leaky ReLU with the slope handed to the optimizer.

186.6 6. Exponential Linear Unit
The exponential linear unit takes a different stance. Rather than a linear negative branch, it uses a saturating exponential that pulls negative inputs toward a bounded floor, \[
\mathrm{ELU}(x) =
\begin{cases}
x & x &gt; 0, \\
\alpha\bigl(e^{x} - 1\bigr) & x \le 0,
\end{cases}
\qquad
\mathrm{ELU}'(x) =
\begin{cases}
1 & x &gt; 0, \\
\alpha e^{x} & x \le 0,
\end{cases}
\] where \(\alpha &gt; 0\) controls the saturation level for large negative inputs, with \(\alpha = 1\) the common choice. As \(x \to -\infty\) the output approaches \(-\alpha\), so the negative branch is bounded below.
def elu(x, alpha=1.0):
    return np.where(x &gt; 0, x, alpha * (np.exp(x) - 1.0))
ELU offers two properties that the linear leak families lack. First, with \(\alpha = 1\) the function is continuously differentiable, including at the origin where the left and right derivatives both equal \(1\), which yields smoother optimization than the kinked ReLU variants. Second, ELU produces negative outputs, so the mean activation of a layer can sit closer to zero. This near zero mean reduces the bias shift that accumulates when every unit emits only nonnegative values, and it pushes the unit closer to its natural gradient, which can accelerate learning. Because the negative branch saturates, ELU is also somewhat robust to noise in the negative regime, since large negative pre-activations all map to roughly \(-\alpha\).
The tradeoffs are real. Evaluating \(e^{x}\) is more expensive than a comparison, so ELU layers are slower than ReLU layers, a difference that can matter at scale. The saturation that helps with robustness also means the negative gradient \(\alpha e^{x}\) shrinks toward zero for very negative inputs, so ELU partially reintroduces the saturation that ReLU was designed to avoid, though only on one side and only in the deep negative tail. A self normalizing variant, the scaled ELU or SELU, fixes \(\alpha\) and a scale constant to specific values so that activations converge to zero mean and unit variance under suitable conditions, which can replace explicit normalization in certain fully connected architectures.

219.2 2. Protocol Architecture and Formal Specification

219.2.1 2.1 Architectural Overview
MCP follows a client-host-server architecture with clear separation of concerns. The host process acts as the primary coordinator, managing lifecycle, permissions, and AI/LLM integration. Each host instantiates one or more clients, where each client maintains a stateful 1:1 connection with a specific server. Servers expose capabilities through standardized primitives.





