// Bagging by averaging the mean response of bootstrap resamples
// (a degenerate depth-0 base learner) to show the resample/aggregate core.
use rand::Rng;

fn bag_predict(ytr: &[f64], b: usize, seed: u64) -&gt; f64 {
    let mut rng = rand::rngs::StdRng::seed_from_u64(seed);
    let n = ytr.len();
    let mut acc = 0.0;
    for _ in 0..b {
        // one bootstrap resample, base learner = sample mean
        let mut s = 0.0;
        for _ in 0..n {
            s += ytr[rng.gen_range(0..n)];
        }
        acc += s / n as f64;
    }
    acc / b as f64 // aggregate by averaging
}

